= {@p_masken[1]*m_masken[3] + p_handschuhe[1]*m_handschuhe[3]@}
\]
\[
P^P = \frac{@p_masken[3]*m_masken[3] + p_handschuhe[3]*m_handschuhe[3]@}{@p_masken[1]*m_masken[3] + p_handschuhe[1]*m_handschuhe[3]@}
\approx {@round((p_masken[3]*m_masken[3] + p_handschuhe[3]*m_handschuhe[3])/(p_masken[1]*m_masken[3] + p_handschuhe[1]*m_handschuhe[3]),3)@}
\]</p>", "final_answers": [{"input_name": "ans1", "answer": "1.228"}]}
